{
  "nl": {
    "issue": [
      {
        "text": "供用电合同如何界定，履行地点如何确定，供电人与用电人各负何种义务、违反义务如何承担责任",
        "rules": [
          "c648-def",
          "c650-1",
          "c650-2",
          "c651-1",
          "c651-2",
          "c652-1",
          "c652-2",
          "c653-1",
          "c653-2",
          "c654-1",
          "c654-2",
          "c654-3",
          "c654-4"
        ]
      },
      {
        "text": "向社会公众供电的供电人是否负有强制缔约义务，能否拒绝用电人的订约要求",
        "rules": [
          "c648-2"
        ]
      },
      {
        "text": "供用水、供用气、供用热力合同适用何种规则",
        "rules": [
          "c656"
        ]
      }
    ],
    "conditions": [
      {
        "text": "供电人向社会公众供电，用电人提出合理的订立合同要求",
        "rules": [
          "c648-2"
        ]
      },
      {
        "text": "当事人约定了供用电合同的履行地点",
        "rules": [
          "c650-1"
        ]
      },
      {
        "text": "当事人对履行地点没有约定或者约定不明确，且存在供电设施的产权分界处",
        "rules": [
          "c650-2"
        ]
      },
      {
        "text": "供电人因供电设施计划检修、临时检修、依法限电或者用电人违法用电等原因需要中断供电",
        "rules": [
          "c652-1",
          "c652-2"
        ]
      },
      {
        "text": "因自然灾害等原因断电",
        "rules": [
          "c653-1",
          "c653-2"
        ]
      },
      {
        "text": "用电人逾期不支付电费；经催告后在合理期限内仍不支付电费和违约金",
        "rules": [
          "c654-2",
          "c654-3"
        ]
      },
      {
        "text": "供电人依据前款规定中止供电",
        "rules": [
          "c654-4"
        ]
      },
      {
        "text": "合同标的为水、气、热力的供用",
        "rules": [
          "c656"
        ]
      }
    ],
    "exceptions": [
      {
        "text": "用电人提出的订约要求须为通常、合理的要求；明显不合理或超出正常需求范围的，不属于强制缔约保护范围",
        "rules": [
          "c648-2"
        ]
      },
      {
        "text": "供电人已按国家有关规定事先通知用电人，或断电后已及时抢修的，不构成义务违反，不承担赔偿责任",
        "rules": [
          "c652-1",
          "c652-2",
          "c653-1",
          "c653-2"
        ]
      },
      {
        "text": "用电人未逾期不付电费，或虽逾期但未经催告、催告后合理期限内已支付的，供电人不得中止供电",
        "rules": [
          "c654-3"
        ]
      }
    ],
    "effects": [
      {
        "text": "供电人应当按照国家规定的供电质量标准和约定安全供电；未按标准供电造成用电人损失的，应当承担赔偿责任",
        "rules": [
          "c651-1",
          "c651-2"
        ]
      },
      {
        "text": "需要中断供电的，供电人应当事先通知用电人；未事先通知即中断供电造成损失的，应当承担赔偿责任",
        "rules": [
          "c652-1",
          "c652-2"
        ]
      },
      {
        "text": "因自然灾害等原因断电的，供电人应当及时抢修；未及时抢修造成损失的，应当承担赔偿责任",
        "rules": [
          "c653-1",
          "c653-2"
        ]
      },
      {
        "text": "用电人应当及时支付电费；逾期不付的应按约定支付违约金；经催告仍不支付电费和违约金的，供电人可以按国家规定的程序中止供电，并应当事先通知用电人",
        "rules": [
          "c654-1",
          "c654-2",
          "c654-3",
          "c654-4"
        ]
      },
      {
        "text": "履行地点按当事人约定；没有约定或者约定不明确的，以供电设施的产权分界处为履行地点",
        "rules": [
          "c650-1",
          "c650-2"
        ]
      },
      {
        "text": "向社会公众供电的供电人不得拒绝用电人合理的订立合同要求（强制缔约）",
        "rules": [
          "c648-2"
        ]
      },
      {
        "text": "供用水、供用气、供用热力合同参照适用供用电合同的有关规定",
        "rules": [
          "c656"
        ]
      },
      {
        "text": "供用电合同在性质上属特殊买卖合同，买卖合同关于财产所有权移转的规定可参照适用",
        "rules": [
          "c648-doc"
        ]
      }
    ],
    "priority": [
      {
        "text": "履行地点以当事人约定优先；无约定或约定不明确时才适用供电设施产权分界处的法定默认规则",
        "rules": [
          "c650-1",
          "c650-2"
        ]
      },
      {
        "text": "强制缔约义务优先于一般合同自由，供电人不得以格式条款或专营地位排除，仅得以请求不合理为由拒绝",
        "rules": [
          "c648-2"
        ]
      },
      {
        "text": "供电人依欠费中止供电的权利，须受国家规定程序及事先通知义务的限制",
        "rules": [
          "c654-3",
          "c654-4"
        ]
      }
    ],
    "distinguish": [
      {
        "text": "供用电合同与一般买卖合同：虽属特殊买卖合同、可参照所有权移转规定，但具有主体特定、垄断经营、继续性履行和公益性的特征，并受强制缔约约束",
        "rules": [
          "c648-doc"
        ]
      },
      {
        "text": "供用水、供用气、供用热力合同是“参照适用”供用电合同规定，而非直接适用",
        "rules": [
          "c656"
        ]
      },
      {
        "text": "笔记所列用电人“保持安全、节约和计划用电”义务及停限电时的配合协助义务，规定于第655条，本行未挂载该条，故不形式化",
        "rules": []
      },
      {
        "text": "LEGO 卡片称“当事人明确约定履行地点即不适用产权分界处规则”与第650条一致；但其“产权分界处不存在或无法确定”的例外并非法条所定，法条仅以“没有约定或者约定不明确”为默认规则的适用条件",
        "rules": [
          "c650-2"
        ]
      }
    ]
  },
